export default function ListView({ pictures }: ListViewProps) {
    const [query, setQuery] = useState('');
    const [sortField, setSortField] = useState<'title' | 'date'>('date');
    const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc');
