        <iframe
            className={styles.media}
            src={picture.url}
            title={picture.title}
            allow="fullscreen; picture-in-picture"
            allowFullScreen
        />
        );
    }

    return (
    <article className={styles.detail}>
      <nav className={styles.pager}>
        <Link to={`/apod/${prev.date}`}>← Previous</Link>
        <Link to={`/apod/${next.date}`}>Next →</Link>
