import { Routes, Route, Link, NavLink } from "react-router";
import styles from "./App.module.css";
import DetailView from "./pages/DetailView.tsx";
import GalleryView from "./pages/GalleryView.tsx";
import ListView from "./pages/ListView.tsx";
import { useState, useEffect } from "react";
import { fetchPictures } from "./api/apod.ts";
import type { ApodPicture } from "./types.ts";

function App() {
  const [pictures, setPictures] = useState<ApodPicture[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchPictures()
      .then((data) => setPictures(data))
      .catch(() => setError('Could not load pictures from NASA. Please try again later.'))
      .finally(() => setLoading(false));
  }, []);

  return (
    <>
      <header className={styles.header}>
        <Link to="/" className={styles.brand}>
          Astronomy Picture of the Day
        </Link>
        <nav>
          <ul className={styles.nav}>
            <li>
              <NavLink
                to="/"
                end
                className={({ isActive }) =>
                  isActive ? styles.activeLink : styles.link
                }
              >
                List
              </NavLink>
            </li>
            <li>
              <NavLink
                to="/gallery"
                className={({ isActive }) =>
                  isActive ? styles.activeLink : styles.link
                }
              >
                Gallery
              </NavLink>
            </li>
          </ul>
        </nav>
      </header>

      <main className={styles.main}>
        {loading && <p className={styles.status}>Loading...</p>}
        {error && <p className={styles.error}>{error}</p>}

        <Routes>
          <Route path="/" element={<ListView pictures={pictures} />} />
          <Route
            path="/gallery"
            element={<GalleryView pictures={pictures} />}
          />
          <Route
            path="/apod/:date"
            element={<DetailView pictures={pictures} loading={loading} />}
          />
        </Routes>
      </main>
    </>
  );
}

export default App;

export interface ApodPicture {
  date: string;
  title: string;
  explanation: string;
  url: string;
  hdurl?: string;
  media_type: "image" | "video";
  copyright?: string;
  thumbnail_url?: string;
  alt?: string;
  permalink?: string;
}

export interface DetailNavState {
  dates: string[];
}

import type { ApodPicture } from "./types";

export function getYouTubeThumbnail(url: string): string | undefined {
  const match = url.match(/youtube(?:-nocookie)?\.com\/embed\/([\w-]+)/);
  return match
    ? `https://img.youtube.com/vi/${match[1]}/hqdefault.jpg`
    : undefined;
}

export function getImageUrl(picture: ApodPicture): string | undefined {
  if (picture.media_type === "image") return picture.url;
  return picture.thumbnail_url ?? getYouTubeThumbnail(picture.url);
}

export function formatMonth(month: string): string {
  return new Date(`${month}-01T00:00:00`).toLocaleDateString("en-US", {
    month: "long",
    year: "numeric",
  });
}

export function isVideoFile(url: string): boolean {
  return /\.(mp4|webm|ogg)$/i.test(url);
}

import axios from 'axios';
import type { ApodPicture } from '../types';

const BASE_URL = 'https://science.nasa.gov/wp-json/wp/v2/apod-basic';
const API_KEY = 'lFrNUZtPXsnNpSx4YCPLyO6XtVr65Bnfa83LsRVW'

interface RawApodEntry {
  date: string;
  title: string;
  media_type: string;
  explanation: string;
  copyright?: string;
  alt?: string;
  url: string;
  hdurl?: string;
  permalink: string;
  basic_html?: string;
}

function htmlToText(html: string | undefined): string {
  if (!html) return '';
  const doc = new DOMParser().parseFromString(html, 'text/html');
  return (doc.body.textContent ?? '').trim();
}

function findVideoUrl(basicHtml: string | undefined): string | undefined {
  if (!basicHtml) return undefined;
  const doc = new DOMParser().parseFromString(basicHtml, 'text/html');
  const player = doc.querySelector('iframe[src], video[src], video source[src]');
  const src = player?.getAttribute('src');
  return src ? new URL(src, 'https://science.nasa.gov/').href : undefined;
}

function toPicture(raw: RawApodEntry): ApodPicture {
  const isVideo = raw.media_type === 'video' || raw.media_type === 'iframe';
  const mainText = raw.explanation.split('<br><br>')[0];

  return {
    date: raw.date,
    title: htmlToText(raw.title),
    explanation: htmlToText(mainText).replace(/^Explanation:\s*/, ''),
    media_type: isVideo ? 'video' : 'image',
    url: isVideo ? (findVideoUrl(raw.basic_html) ?? raw.url) : (raw.hdurl ?? raw.url),
    hdurl: raw.hdurl,
    copyright: htmlToText(raw.copyright).replace(/^Image Credit:\s*/, '') || undefined,
    alt: raw.alt,
    permalink: raw.permalink,
  };
}

function toDateId(date: Date): string {
  const yy = String(date.getFullYear()).slice(2);
  const mm = String(date.getMonth() + 1).padStart(2, '0');
  const dd = String(date.getDate()).padStart(2, '0');
  return `${yy}${mm}${dd}`;
}

async function fetchOne(dateId: string): Promise<ApodPicture> {
  const response = await axios.get<RawApodEntry>(`${BASE_URL}/${dateId}`, {
    params: { api_key: API_KEY },
  });
  return toPicture(response.data);
}

async function fetchFromNasa(totalDays = 150): Promise<ApodPicture[]> {
  const response = await axios.get<RawApodEntry[]>(BASE_URL, {
    params: { api_key: API_KEY },
  });
  const latest = response.data.map(toPicture);

  const earliest = latest.reduce((min, p) => (p.date < min ? p.date : min), latest[0].date);
  const cursor = new Date(`${earliest}T00:00:00`);
  const olderIds: string[] = [];
  for (let i = latest.length; i < totalDays; i++) {
    cursor.setDate(cursor.getDate() - 1);
    olderIds.push(toDateId(cursor));
  }

  const results = await Promise.allSettled(olderIds.map(fetchOne));
  const older = results
    .filter((r): r is PromiseFulfilledResult<ApodPicture> => r.status === 'fulfilled')
    .map((r) => r.value);

  return [...latest, ...older].sort((a, b) => a.date.localeCompare(b.date));
}

const CACHE_KEY = 'apod-pictures';

export async function fetchPictures(totalDays = 150): Promise<ApodPicture[]> {
  const cached = sessionStorage.getItem(CACHE_KEY);
  if (cached) return JSON.parse(cached) as ApodPicture[];

  const pictures = await fetchFromNasa(totalDays);
  sessionStorage.setItem(CACHE_KEY, JSON.stringify(pictures));
  return pictures;
}

import { Link, useParams, useLocation } from "react-router";
import type { ApodPicture, DetailNavState } from "../types";
import styles from "./DetailView.module.css";
import { isVideoFile } from "../utils";

interface DetailViewProps {
  pictures: ApodPicture[];
  loading: boolean;
}

export default function DetailView({ pictures, loading }: DetailViewProps) {
  const { date } = useParams();
  const location = useLocation();

  if (loading) return null;

  const picture = pictures.find((p) => p.date === date);

  if (!picture) {
    return (
      <p>
        No picture found for {date}. <Link to="/">Back to the list</Link>
      </p>
    );
  }

  const navState = location.state as DetailNavState | null;
  const sequence = navState?.dates && navState.dates.includes(picture.date) ? navState.dates : pictures.map((p) => p.date);

  const position = sequence.indexOf(picture.date);
  const prevDate = sequence[(position - 1 + sequence.length) % sequence.length];
  const nextDate = sequence[(position + 1) % sequence.length];
  const nextState: DetailNavState = { dates: sequence };

  let media;
  if (picture.media_type === "image") {
    media = (
      <img className={styles.media} src={picture.url} alt={picture.alt ?? picture.title} />
    );
  } else if (isVideoFile(picture.url)) {
    media = <video className={styles.media} src={picture.url} controls />;
  } else {
    media = (
      <iframe
        className={styles.media}
        src={picture.url}
        title={picture.title}
        allow="fullscreen; picture-in-picture"
        allowFullScreen
      />
    );
  }

  return (
    <article className={styles.detail}>
      <nav className={styles.pager}>
        <Link to={`/apod/${prevDate}`} state={nextState}>
          ← Previous
        </Link>
        <span className={styles.meta}>
          {position + 1} of {sequence.length}
        </span>
        <Link to={`/apod/${nextDate}`} state={nextState}>
          Next →
        </Link>
      </nav>

      <h1>{picture.title}</h1>
      <p className={styles.meta}>
        {picture.date}
        {picture.copyright && ` · © ${picture.copyright}`}
      </p>

      {media}

      {picture.media_type === "video" && (
        <p className={styles.meta}>
          Video not playing?{" "}
          <a href={picture.permalink ?? picture.url} target="_blank" rel="noreferrer">
            Open it in a new tab
          </a>
        </p>
      )}

      <p className={styles.explanation}>{picture.explanation}</p>
    </article>
  );
}

import type { ApodPicture } from "../types";
import { getImageUrl, isVideoFile } from "../utils";
import styles from "./Thumbnail.module.css";

interface ThumbnailProps {
  picture: ApodPicture;
  className?: string;
}

export default function Thumbnail({ picture, className = "" }: ThumbnailProps) {
  const imageUrl = getImageUrl(picture);
  const classes = `${styles.thumb} ${className}`;

  if (imageUrl) {
    return (
      <img
        className={classes}
        src={imageUrl}
        alt={picture.alt ?? picture.title}
        loading="lazy"
      />
    );
  }

  if (isVideoFile(picture.url)) {
    return (
      <video
        className={classes}
        src={`${picture.url}#t=0.1`}
        muted
        preload="metadata"
        aria-label={picture.title}
      />
    );
  }

  return (
    <div
      className={`${classes} ${styles.placeholder}`}
      role="img"
      aria-label={picture.title}
    >
      ▶
    </div>
  );
}

